<script setup>import {money} from '../core';import Icon from './Icon.vue';defineProps({product:Object});</script><template><RouterLink :to="'/shop/'+product.id" class="product-card"><div class="product-photo"><img :src="product.image" :alt="product.name" loading="lazy"><span v-if="!product.stock" class="photo-label">暂时缺货</span><span v-else-if="product.recommended" class="photo-label">贴心推荐</span></div><p class="eyebrow">{{product.category}}</p><h3>{{product.name}}</h3><div class="row between"><strong class="price">¥{{money(product.price)}}</strong><span class="round-button"><Icon name="plus" :size="17"/></span></div></RouterLink></template>
